def solve(inputs: dict) -> float:
    import json

    # Parse input
    M = inputs.get('M')
    power = inputs.get('power', 29)
    mod = inputs.get('mod', 695754)

    # Handle both list and string representations
    if isinstance(M, str):
        M = json.loads(M)

    # Matrix multiplication with modulo
    def mat_mult(A, B, mod):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation using binary exponentiation
    def mat_pow(M, n, mod):
        if n == 0:
            return [[1, 0], [0, 1]]  # Identity matrix
        if n == 1:
            return [[M[0][0] % mod, M[0][1] % mod], 
                    [M[1][0] % mod, M[1][1] % mod]]

        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [[M[0][0] % mod, M[0][1] % mod], 
                [M[1][0] % mod, M[1][1] % mod]]

        while n > 0:
            if n % 2 == 1:
                result = mat_mult(result, base, mod)
            base = mat_mult(base, base, mod)
            n //= 2

        return result

    # Compute M^29
    result = mat_pow(M, power, mod)

    # Sum all entries
    total = sum(result[0]) + sum(result[1])
    return float(total % mod)

